async function ajouterVente(chemin, vente) {
  await fs.writeFile(chemin, JSON.stringify([vente]));
  return 1;
}

solution:
const fs = require("fs").promises;

async function ajouterVente(chemin, vente) {
  let ventes = [];
  try {
    ventes = JSON.parse(await fs.readFile(chemin, "utf8"));
  } catch (erreur) {
    if (erreur.code !== "ENOENT") throw erreur;
  }
  ventes.push(vente);
  await fs.writeFile(chemin, JSON.stringify(ventes, null, 2));
  return ventes.length;
}
